'use strict';
class CityFilters{
 constructor(onChange){this.onChange=onChange;this.nomads=new Map();this.homicide=new Map();this.cityHomicide=new Map();this.ready=false;this.error=false;this.q=new URLSearchParams(location.search);this.committed=null;this.ids=['city-map-effect','nomads-enabled','nomads-min','cost-enabled','cost-max','crime-enabled','crime-max','crime-year','crime-geography'];for(const id of this.ids)document.getElementById(id).addEventListener('change',()=>{this.sync();onChange();});for(const [q,id]of [['nomads','nomads-enabled'],['cost','cost-enabled'],['crime','crime-enabled']])document.getElementById(id).checked=this.q.get(q)==='1';document.getElementById('city-map-effect').value=this.q.get('citymap')==='ranking'?'ranking':'markers';for(const [q,id,min,max,step]of [['nomadmin','nomads-min',0,5,.1],['budget','cost-max',0,1000000,50],['hommax','crime-max',0,300,.1]]){const v=Number(this.q.get(q));if(this.q.has(q)&&Number.isFinite(v)&&v>=min&&v<=max&&Math.abs(v/step-Math.round(v/step))<1e-7)document.getElementById(id).value=v;}const initialYear=document.getElementById('crime-year');initialYear.replaceChildren();for(let year=2025;year>=2020;year--){const o=document.createElement('option');o.value=String(year);o.textContent=String(year);initialYear.append(o);}initialYear.value=[...initialYear.options].some(o=>o.value===this.q.get('homyear'))?this.q.get('homyear'):'2024';document.getElementById('crime-geography').value=this.q.get('homgeo')==='country'||(!this.q.has('homgeo')&&this.q.get('crime')==='1')?'country':'city';const initialPop=document.getElementById('rank-population');if([...initialPop.options].some(o=>o.value===this.q.get('pop')))initialPop.value=this.q.get('pop');document.getElementById('city-filter-reset').onclick=()=>{this.q=new URLSearchParams();document.getElementById('rank-population').value='50000';document.getElementById('city-map-effect').value='markers';for(const id of ['nomads-enabled','cost-enabled','crime-enabled'])document.getElementById(id).checked=false;document.getElementById('nomads-min').value=3;document.getElementById('cost-max').value=2500;document.getElementById('crime-max').value=5;document.getElementById('crime-year').value='2024';document.getElementById('crime-geography').value='city';this.sync();onChange();};for(const id of ['nomads-min','cost-max','crime-max']){const slider=document.getElementById(id+'-slider'),input=document.getElementById(id);slider.addEventListener('input',()=>{input.value=slider.value;this.sync();clearTimeout(this.timer);this.timer=setTimeout(()=>onChange(),120);});input.addEventListener('input',()=>{this.sync();clearTimeout(this.timer);this.timer=setTimeout(()=>onChange(),120);});}document.getElementById('edit-city-filters').onclick=()=>window.ComfyDays?.ui.open('city');this.sync();this.load();}
 async load(){this.error=false;this.ready=false;this.sync();try{const [n,h,c]=await Promise.all([fetch('assets/nomads-cities.json?v=15').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('assets/homicide-country.json?v=16').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('assets/homicide-city.json.gz?v=16').then(async r=>{if(!r.ok)throw Error();return new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json();})]);this.nomadsMeta=n;this.crimeMeta=h;this.cityCrimeMeta=c;for(const row of c.rows){const record=Object.fromEntries(c.columns.map((key,i)=>[key,row[i]]));this.cityHomicide.set(record.id+'|'+record.year,record);}for(const city of n.cities)if(!this.nomads.has(city.id)||city.match_km<this.nomads.get(city.id).match_km)this.nomads.set(city.id,city);for(const r of h.rows)if(r.place_country)this.homicide.set(r.place_country+'|'+r.year,r);const select=document.getElementById('crime-year');select.replaceChildren();for(const year of [...new Set([...Object.keys(h.coverage_by_year),...Object.keys(c.coverage_by_year)])].sort().reverse()){const o=document.createElement('option');o.value=year;o.textContent=year;select.append(o);}select.value='2024';document.getElementById('crime-geography').value=this.q.get('homgeo')==='country'||(!this.q.has('homgeo')&&this.q.get('crime')==='1')?'country':'city';const set=(query,id,min,max,step)=>{const value=Number(this.q.get(query));if(this.q.has(query)&&Number.isFinite(value)&&value>=min&&value<=max&&Math.abs(value/step-Math.round(value/step))<1e-7)document.getElementById(id).value=value;};set('nomadmin','nomads-min',0,5,.1);set('budget','cost-max',0,1000000,50);set('hommax','crime-max',0,300,.1);if([...select.options].some(o=>o.value===this.q.get('homyear')))select.value=this.q.get('homyear');const pop=document.getElementById('rank-population');if([...pop.options].some(o=>o.value===this.q.get('pop')))pop.value=this.q.get('pop');this.ready=true;document.getElementById('nomads-date').textContent=`Nomads · ${new Date(n.retrieved_at).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'America/Sao_Paulo'})} · ${this.nomads.size.toLocaleString('en')} cities. Cost is a nomad estimate.`;this.sync();this.onChange();}catch(e){this.error=true;this.ready=false;this.sync();this.onChange();}}
 sync(){if(this.ready){const s=this.state,counts=this.cityCrimeMeta.coverage_by_year[s.year]||{};document.getElementById('crime-date').textContent=s.geography==='city'?`${s.year} · FBI: ${counts.FBI||0} USA cities, 12 complete months required. Eurostat: ${counts.Eurostat||0} city areas; monthly completeness unknown. No country fallback.`:`${s.year} · UNODC: ${this.crimeMeta.coverage_by_year[s.year]||0} countries/areas. Release ${this.crimeMeta.source_updated}.`;}for(const [toggle,input]of [['nomads-enabled','nomads-min'],['cost-enabled','cost-max'],['crime-enabled','crime-max']])document.getElementById(input).disabled=!this.ready||!document.getElementById(toggle).checked;for(const id of ['crime-year','crime-geography'])document.getElementById(id).disabled=!this.ready||!document.getElementById('crime-enabled').checked;for(const id of ['nomads-enabled','cost-enabled','crime-enabled'])document.getElementById(id).disabled=!this.ready;for(const id of ['nomads-min','cost-max','crime-max']){const slider=document.getElementById(id+'-slider'),input=document.getElementById(id);slider.disabled=input.disabled;slider.value=input.value;}document.getElementById('city-filter-status').textContent=this.error?'City data unavailable. Weather results remain visible.':!this.ready?'Loading city data…':!this.valid()?'Check filter values. Last valid filters remain applied.':this.active?'Applied · unknown data kept.':'Optional filters off.';window.ComfyDays?.ui.refresh();}
 rawState(){const value=id=>{const text=document.getElementById(id).value;return text===''?NaN:Number(text);},checked=id=>document.getElementById(id).checked;return {nomads:checked('nomads-enabled'),minimum:value('nomads-min'),cost:checked('cost-enabled'),budget:value('cost-max'),crime:checked('crime-enabled'),maximum:value('crime-max'),year:value('crime-year'),geography:document.getElementById('crime-geography').value,population:value('rank-population')};}
 get state(){const raw=this.rawState();if(this.valid(raw))this.committed={...raw};return this.committed||raw;}
 get active(){const s=this.state;return s.nomads||s.cost||s.crime;}
 get signature(){return JSON.stringify([this.ready,this.error,this.state]);}
 valid(s=this.rawState()){return (!s.nomads||Number.isFinite(s.minimum)&&s.minimum>=0&&s.minimum<=5)&&(!s.cost||Number.isFinite(s.budget)&&s.budget>=0&&s.budget<=1000000)&&(!s.crime||Number.isFinite(s.maximum)&&s.maximum>=0&&s.maximum<=300);}
 assessment(e){if(!this.active)return {failures:[],missing:[],status:'match'};if(!this.ready)return {failures:[],missing:[this.error?'City data unavailable':'City data loading'],status:'unknown'};const s=this.state,n=this.nomads.get(e.place[0]),h=this.crimeRecord(e.place),failures=[],missing=[];if(s.nomads){if(!Number.isFinite(n?.score))missing.push('Nomads score unavailable');else if(n.score<s.minimum)failures.push(`Nomads ${n.score.toFixed(1)} < ${s.minimum}`);}if(s.cost){if(!Number.isFinite(n?.monthly_cost_usd)||n.monthly_cost_usd<=0)missing.push('Monthly cost unavailable');else if(n.monthly_cost_usd>s.budget)failures.push(`Cost $${Math.round(n.monthly_cost_usd).toLocaleString('en')} > $${s.budget.toLocaleString('en')}`);}if(s.crime){if(!Number.isFinite(h?.value))missing.push(`${this.crimeScope} homicide unavailable (${s.year})`);else if(h.value>s.maximum)failures.push(`${this.crimeScope} homicide ${h.value.toFixed(1)} > ${s.maximum} /100k (${s.year})`);}return {failures,missing,status:failures.length?'fail':missing.length?'unknown':'match'};}
 reasons(e){const a=this.assessment(e);return [...a.failures,...a.missing];}
 allows(e){return this.assessment(e).failures.length===0;}
 description(){const s=this.state;return [`Cities ≥${s.population.toLocaleString('en')}`,...(s.nomads?[`Nomads ≥${s.minimum}/5`]:[]),...(s.cost?[`Budget ≤$${s.budget.toLocaleString('en')}`]:[]),...(s.crime?[`${this.crimeScope} homicide ≤${s.maximum}/100k (${s.year})`]:[])];}
 appendURL(q){const s=this.state;for(const key of ['nomads','nomadmin','cost','budget','crime','hommax','homyear','homgeo','citymap','pop'])q.delete(key);if(s.population!==50000)q.set('pop',s.population);if(this.active||document.getElementById('city-map-effect').value==='ranking')q.set('citymap',document.getElementById('city-map-effect').value);if(s.nomads){q.set('nomads','1');q.set('nomadmin',s.minimum);}if(s.cost){q.set('cost','1');q.set('budget',s.budget);}if(s.crime){q.set('crime','1');q.set('hommax',s.maximum);q.set('homyear',s.year);q.set('homgeo',s.geography);}}
 get crimeScope(){return this.state.geography==='city'?'City':'Country';}
 crimeRecord(place){return this.state.geography==='city'?this.cityHomicide.get(place[0]+'|'+this.state.year):this.homicide.get(place[5]+'|'+this.state.year);}
 details(place){const box=document.getElementById('city-context-values');box.replaceChildren();if(!place){box.textContent='Select a place for city details.';return;}if(!this.ready){box.textContent=this.error?'City data unavailable.':'Loading city data…';return;}const n=this.nomads.get(place[0]),h=this.homicide.get(place[5]+'|'+this.state.year),fmt=v=>v.toLocaleString('en',{maximumFractionDigits:1});const add=(label,value,source,url)=>{const row=document.createElement('div'),term=document.createElement('dt'),desc=document.createElement('dd'),a=document.createElement('a');term.textContent=label;desc.textContent=value+' ';a.textContent=source;a.href=url;a.target='_blank';a.rel='noopener';if(url.startsWith('#'))a.onclick=e=>{e.preventDefault();window.ComfyDays?.ui.open('city');};desc.append(a);row.append(term,desc);box.append(row);return desc;};if(this.active){const a=this.assessment({place});add('City filters',a.failures.length?'Outside filters · '+a.failures.join('; '):a.missing.length?'Kept · '+a.missing.join('; '):'Matches','Edit','#city-panel');}add('Nomads score',Number.isFinite(n?.score)?fmt(n.score)+' / 5':'Unknown','Nomads.com',n?'https://nomads.com/'+n.slug:'https://nomads.com/');add('Nomad cost / month',n?.monthly_cost_usd>0?'$'+fmt(n.monthly_cost_usd)+' USD':'Unknown','Nomads.com',n?'https://nomads.com/'+n.slug:'https://nomads.com/');const local=this.cityHomicide.get(place[0]+'|'+this.state.year);const row=add(`City homicide · ${this.state.year}`,local?`${fmt(local.value)} /100k · ${local.area}`:'Unknown',local?local.source:'FBI / Eurostat',local?this.cityCrimeMeta.source_urls[local.source]:this.cityCrimeMeta.source_urls.Eurostat);if(local){const d=document.createElement('details'),summary=document.createElement('summary'),p=document.createElement('p');summary.textContent='Reporting details';p.textContent=`${local.geography}. ${local.count!==null?local.count+(local.source==='FBI'?' reported murders. ':' homicide victims. '):''}${local.population?'FBI population '+fmt(local.population)+'. ':''}${local.source==='FBI'?'12 complete months required by the source table.':'Annual rate; monthly reporting completeness unknown.'}${local.warning?' '+local.warning:''}`;d.append(summary,p);row.append(d);}add(`Country homicide · ${this.state.year}`,h?`${fmt(h.value)} /100k · ${h.country}`:'Unknown','UNODC','https://data.unodc.org/datareport/hom-victim');}
}
window.CityFilters=CityFilters;
